-- ============================================================================
-- StashInn Portal — Booking email templates
-- Migration: 20261108000000_booking_email_templates
--
-- Adds the booking request emails (customer and partner) and replaces the unused default
-- "booking_confirmed" text with the confirmation that carries the exact address, directions
-- and the location's contact. A booking_confirmed template an admin has already edited is
-- left alone. The app falls back to the same text (packages/lib/src/services/bookingEmails.ts)
-- until this runs.
-- ============================================================================

INSERT INTO public.email_templates (slug, subject, body_html, variables) VALUES
  ('booking_requested', $t$Booking request received · #{{booking_ref}}$t$,
   $t$<h2 style="margin:0 0 12px;font-size:22px;color:#111827;">Hi {{customer_name}}, we've got your request</h2><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#374151;">Your booking request at <strong>{{location_name}}</strong> has been sent to the partner. We'll email you as soon as they confirm it.</p><table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:6px 0 18px;border:1px solid #e5e7eb;border-radius:12px;"><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;">Booking</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;">#{{booking_ref}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Location</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{location_name}}<br/><span style="font-weight:400;color:#6b7280;">{{location_area}}</span></td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Drop-off</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{drop_off}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Pick-up</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{pick_up}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Storing</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{items}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Total</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">₹{{total}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Payment</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{payment_method}}</td></tr></table><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#374151;">The exact address, directions and the partner's contact details are shared with you once the booking is confirmed.</p><p style="margin:22px 0 6px;"><a href="{{dashboard_url}}" style="display:inline-block;background:#ea580c;color:#ffffff;text-decoration:none;font-weight:700;font-size:15px;padding:12px 22px;border-radius:10px;">View my booking</a></p>$t$,
   ARRAY['customer_name', 'booking_ref', 'location_name', 'location_area', 'drop_off', 'pick_up', 'items', 'total', 'payment_method', 'dashboard_url']),

  ('partner_booking_request', $t$New booking request · {{location_name}}$t$,
   $t$<h2 style="margin:0 0 12px;font-size:22px;color:#111827;">New booking request, {{partner_name}}</h2><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#374151;">A customer wants to store with you at <strong>{{location_name}}</strong>. Please accept or decline it soon so they can plan their day.</p><table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:6px 0 18px;border:1px solid #e5e7eb;border-radius:12px;"><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;">Booking</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;">#{{booking_ref}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Customer</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{customer_name}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Drop-off</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{drop_off}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Pick-up</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{pick_up}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Storing</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{items}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Booking total</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">₹{{total}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Your earnings</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">₹{{partner_amount}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Payment</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{payment_method}}</td></tr></table><p style="margin:22px 0 6px;"><a href="{{dashboard_url}}" style="display:inline-block;background:#ea580c;color:#ffffff;text-decoration:none;font-weight:700;font-size:15px;padding:12px 22px;border-radius:10px;">Accept or decline</a></p>$t$,
   ARRAY['partner_name', 'booking_ref', 'location_name', 'customer_name', 'drop_off', 'pick_up', 'items', 'total', 'partner_amount', 'payment_method', 'dashboard_url'])
ON CONFLICT (slug) DO NOTHING;

UPDATE public.email_templates
SET subject = $t$Booking confirmed · {{location_name}}$t$,
    body_html = $t$<h2 style="margin:0 0 12px;font-size:22px;color:#111827;">You're all set, {{customer_name}}</h2><p style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#374151;"><strong>{{location_name}}</strong> has confirmed your booking. Here's everything you need for drop-off.</p><div style="margin:6px 0 18px;padding:16px;border-radius:12px;background:#fff7ed;border:1px solid #fed7aa;text-align:center;"><div style="font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#9a3412;">Check-in code</div><div style="font-size:32px;font-weight:900;letter-spacing:.25em;color:#111827;margin-top:4px;">{{checkin_otp}}</div><div style="font-size:13px;color:#6b7280;margin-top:4px;">Give this code to the partner when you drop off.</div></div><table role="presentation" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;margin:6px 0 18px;border:1px solid #e5e7eb;border-radius:12px;"><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;">Booking</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;">#{{booking_ref}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Address</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{address}}<br/><a href="{{directions_url}}" style="color:#ea580c;font-weight:700;">Get directions</a></td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Contact</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{contact_name}}<br/><a href="tel:{{contact_phone}}" style="color:#ea580c;font-weight:700;">{{contact_phone}}</a></td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Drop-off</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{drop_off}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Pick-up</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{pick_up}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Storing</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">{{items}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#6b7280;width:38%;border-top:1px solid #f3f4f6;">Total</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#111827;border-top:1px solid #f3f4f6;">₹{{total}}</td></tr></table><p style="margin:22px 0 6px;"><a href="{{dashboard_url}}" style="display:inline-block;background:#ea580c;color:#ffffff;text-decoration:none;font-weight:700;font-size:15px;padding:12px 22px;border-radius:10px;">View my booking</a></p>$t$,
    variables = ARRAY['customer_name', 'booking_ref', 'location_name', 'address', 'directions_url', 'contact_name', 'contact_phone', 'drop_off', 'pick_up', 'items', 'total', 'checkin_otp', 'dashboard_url'],
    updated_at = now()
WHERE slug = 'booking_confirmed'
  AND subject = 'Your StashInn Booking is Confirmed! 🎒'
  AND body_html LIKE '<h2>Hi {{customer_name}},</h2><p>Your booking <strong>#{{booking_id}}</strong>%';
